import java.util.*;

public class Main {
    static long best(long[][] workers, long[][] bikes, int i, int used, Map<Integer, Long> memo) {
        if (i == workers.length) return 0;
        Long found = memo.get(used);
        if (found != null) return found;
        long result = 1000000000L;
        for (int j = 0; j < bikes.length; j++) {
            if (((used >> j) & 1) == 0) {
                long d = Math.abs(workers[i][0] - bikes[j][0]) + Math.abs(workers[i][1] - bikes[j][1]);
                result = Math.min(result, d + best(workers, bikes, i + 1, used | (1 << j), memo));
            }
        }
        memo.put(used, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long w = sc.nextLong();
        long b = sc.nextLong();
        long[][] workers = new long[(int) w][2];
        for (int i = 0; i < workers.length; i++) {
            for (int j = 0; j < workers[i].length; j++) {
                workers[i][j] = sc.nextLong();
            }
        }
        long[][] bikes = new long[(int) b][2];
        for (int i = 0; i < bikes.length; i++) {
            for (int j = 0; j < bikes[i].length; j++) {
                bikes[i][j] = sc.nextLong();
            }
        }

        System.out.println(best(workers, bikes, 0, 0, new HashMap<>()));
    }
}
